(function() {
    'use strict';

    class CopanReputationAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Crisis de Reputación Online';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleEn: 'Round 1: Crisis Assessment',
                    titleEs: 'Ronda 1: Evaluación de Crisis',
                    descEn: '<b>Monday morning — post-crisis weekend.</b><br><br>TripAdvisor shows 3 new negative reviews (avg 1.7/5). An influencer with 200K followers posted <b>#HaciendaCopanFail</b> on X — 5,000 likes, 1,200 retweets. Google rating dropped from 4.6 to 4.3.<br><br><b>Choose your assessment strategy:</b><br>A — Immediate comprehensive monitoring: deploy team to track all platforms, draft response plan within hours<br>B — Wait 24 hours: observe whether the situation escalates before acting<br>C — Basic social media monitoring: track mentions but take no action yet<br>D — Ignore the crisis: assume negative attention will fade on its own<br>E — Hire external crisis management consultant for expert assessment',
                    descEs: '<b>Lunes por la mañana — post fin de semana de crisis.</b><br><br>TripAdvisor muestra 3 reseñas negativas nuevas (promedio 1.7/5). Un influencer con 200K seguidores publicó <b>#HaciendaCopanFail</b> en X — 5,000 likes, 1,200 retweets. La calificación de Google bajó de 4.6 a 4.3.<br><br><b>Elige tu estrategia de evaluación:</b><br>A — Monitoreo integral inmediato: desplegar equipo para rastrear todas las plataformas, plan de respuesta en horas<br>B — Esperar 24 horas: observar si la situación escala antes de actuar<br>C — Monitoreo básico de redes: rastrear menciones sin tomar acción<br>D — Ignorar la crisis: asumir que la atención negativa se desvanecerá sola<br>E — Contratar consultor externo de gestión de crisis para evaluación experta',
                    stratEn: ['A: Immediate comprehensive monitoring', 'B: Wait and observe (24h)', 'C: Basic social media monitoring', 'D: Ignore the crisis', 'E: Hire crisis consultant'],
                    stratEs: ['A: Monitoreo integral inmediato', 'B: Esperar y observar (24h)', 'C: Monitoreo básico de redes', 'D: Ignorar la crisis', 'E: Contratar consultor de crisis']
                },
                {
                    titleEn: 'Round 2: Response Strategy',
                    titleEs: 'Ronda 2: Estrategia de Respuesta',
                    descEn: '<b>Time to respond publicly.</b><br><br>The crisis is now 48 hours old. Your assessment is complete. You must decide how to respond to affected guests and the public.<br><br><b>Choose your response approach:</b><br>A — No public response: handle complaints privately if guests contact you<br>B — Defensive response: post public replies disagreeing with negative reviews<br>C — Apologize + compensate: public apology on all platforms + $300 refund per affected guest (30 guests)<br>D — Full service recovery: apology + $300 refund + free retry visit for reviewers (3 guests)<br>E — Influencer engagement: invite the 200K-follower influencer for a free 3-night redemption stay',
                    descEs: '<b>Es hora de responder públicamente.</b><br><br>La crisis tiene ya 48 horas. Tu evaluación está completa. Debes decidir cómo responder a los huéspedes afectados y al público.<br><br><b>Elige tu enfoque de respuesta:</b><br>A — Sin respuesta pública: manejar quejas en privado si los huéspedes contactan<br>B — Respuesta defensiva: publicar réplicas en desacuerdo con reseñas negativas<br>C — Disculpa + compensación: disculpa pública en todas las plataformas + reembolso de $300 por huésped afectado (30 huéspedes)<br>D — Recuperación completa del servicio: disculpa + $300 reembolso + visita gratis para los que dejaron reseñas (3 huéspedes)<br>E — Engagement con influencer: invitar al influencer de 200K seguidores a una estadía de redención gratuita de 3 noches',
                    stratEn: ['A: No public response', 'B: Defensive response to reviews', 'C: Apologize + $300 refund per guest', 'D: Full recovery (C + free retry visits)', 'E: Influencer redemption invitation'],
                    stratEs: ['A: Sin respuesta pública', 'B: Respuesta defensiva a reseñas', 'C: Disculpa + $300 reembolso por huésped', 'D: Recuperación completa (C + visitas gratuitas)', 'E: Invitación de redención al influencer']
                },
                {
                    titleEn: 'Round 3: Recovery Monitoring',
                    titleEs: 'Ronda 3: Monitoreo de Recuperación',
                    descEn: '<b>One week after the crisis (March 7–14).</b><br><br>Booking.com reports 5 cancellations ($6,000 lost revenue) from guests who saw the negative reviews. Projections indicate 15–20% booking loss over the next 2 months if reputation damage persists.<br><br><b>Choose your recovery strategy:</b><br>A — Cancellation recovery: contact guests who cancelled, offer $150 discount to rebook<br>B — Early booking incentive: 10% discount for bookings made 4+ months in advance<br>C — Hire a dedicated reputation manager to respond to all new reviews within 24 hours<br>D — Combined approach: apply strategies A + B + C together<br>E — Launch a marketing campaign highlighting positive guest experiences and the Mayan site',
                    descEs: '<b>Una semana después de la crisis (7–14 de marzo).</b><br><br>Booking.com reporta 5 cancelaciones ($6,000 de ingresos perdidos) de huéspedes que vieron las reseñas negativas. Las proyecciones indican una pérdida de 15–20% en reservas durante los próximos 2 meses si persiste el daño reputacional.<br><br><b>Elige tu estrategia de recuperación:</b><br>A — Recuperación de cancelaciones: contactar huéspedes que cancelaron, ofrecer $150 de descuento para reprogramar<br>B — Incentivo de reserva anticipada: 10% de descuento para reservas hechas con 4+ meses de anticipación<br>C — Contratar un gestor de reputación dedicado para responder a todas las reseñas nuevas en 24 horas<br>D — Enfoque combinado: aplicar estrategias A + B + C juntas<br>E — Lanzar campaña de marketing destacando experiencias positivas y el sitio Maya',
                    stratEn: ['A: Cancellation recovery discounts', 'B: Early booking incentives', 'C: Hire reputation manager', 'D: Combined approach (A+B+C)', 'E: Marketing campaign'],
                    stratEs: ['A: Descuentos de recuperación de cancelaciones', 'B: Incentivos de reserva anticipada', 'C: Contratar gestor de reputación', 'D: Enfoque combinado (A+B+C)', 'E: Campaña de marketing']
                },
                {
                    titleEn: 'Round 4: Prevention Plan',
                    titleEs: 'Ronda 4: Plan de Prevención',
                    descEn: '<b>Present your Operational Excellence plan to the board.</b><br><br>The immediate crisis is being managed. Now you must invest in systems to prevent future cascading failures. Your annual prevention budget determines the scope of improvements.<br><br><b>Choose your prevention focus:</b><br>A — Staffing: backup cook + tour guide buffer + weekend coverage plan ($30K/yr)<br>B — IT infrastructure: WiFi redundancy + failover systems ($10K capex + $2K/yr)<br>C — Quality assurance: daily manager stand-ups + service recovery fund ($24K/yr)<br>D — Balanced investment: moderate allocation across staffing, IT, and QA<br>E — Comprehensive: all systems at full investment — staffing, IT, QA, and dedicated reputation manager ($72K/yr)',
                    descEs: '<b>Presenta tu plan de Excelencia Operacional al directorio.</b><br><br>La crisis inmediata se está manejando. Ahora debes invertir en sistemas para prevenir futuras fallas en cascada. Tu presupuesto anual de prevención determina el alcance de las mejoras.<br><br><b>Elige tu enfoque de prevención:</b><br>A — Personal: cocinero de respaldo + guías adicionales + plan de cobertura de fines de semana ($30K/año)<br>B — Infraestructura IT: redundancia WiFi + sistemas de failover ($10K capex + $2K/año)<br>C — Aseguramiento de calidad: reuniones diarias de gerentes + fondo de recuperación de servicio ($24K/año)<br>D — Inversión balanceada: asignación moderada entre personal, IT y calidad<br>E — Integral: todos los sistemas a inversión completa — personal, IT, calidad y gestor de reputación dedicado ($72K/año)',
                    stratEn: ['A: Staffing focus ($30K/yr)', 'B: IT infrastructure ($10K+$2K/yr)', 'C: Quality assurance + recovery fund ($24K/yr)', 'D: Balanced investment across all areas', 'E: Comprehensive — all systems ($72K/yr)'],
                    stratEs: ['A: Enfoque en personal ($30K/año)', 'B: Infraestructura IT ($10K+$2K/año)', 'C: Calidad + fondo de recuperación ($24K/año)', 'D: Inversión balanceada en todas las áreas', 'E: Integral — todos los sistemas ($72K/año)']
                }
            ];
        }

        _t(key, vars) {
            try { if (window.mySimulation && typeof window.mySimulation.t === 'function') return window.mySimulation.t(key, vars); } catch (e) {}
            return key;
        }
        _lang() {
            try {
                var m = window.mySimulation || {};
                var l = m.currentLanguage || m.language || (window.vcI18n && (window.vcI18n.lang || window.vcI18n.currentLanguage)) || 'en';
                return (String(l).toLowerCase().indexOf('es') === 0) ? 'es' : 'en';
            } catch (e) { return 'en'; }
        }
        _computeScore(rep, sent, book, totalSpent) {
            var score = 0;
            if (rep >= 4.7) score += 30; else if (rep >= 4.5) score += 20; else if (rep >= 4.2) score += 10;
            if (sent >= 70) score += 25; else if (sent >= 50) score += 15; else if (sent >= 30) score += 5;
            if (book >= 85) score += 25; else if (book >= 75) score += 15; else if (book >= 60) score += 5;
            if (totalSpent <= 50000) score += 20; else if (totalSpent <= 80000) score += 10;
            return Math.max(0, Math.min(100, score));
        }
        _tierFor(score) { if (score >= 80) return 'excellent'; if (score >= 60) return 'good'; if (score >= 40) return 'adequate'; return 'needs_improvement'; }
        _gradeFor(score) { if (score >= 85) return 'A'; if (score >= 70) return 'B'; if (score >= 55) return 'C'; if (score >= 40) return 'D'; return 'F'; }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 200000,
                    reputationTA: 4.60,
                    reputationGoogle: 4.30,
                    socialSentiment: 35,
                    bookingsNextMonth: 75,
                    totalRecoveryCost: 0,
                    reputationHistory: [],
                    bookingHistory: [],
                    sentimentHistory: [],
                    performance: { overallScore: 0, grade: 'F', tier: 'needs_improvement' },
                    _snap: {}
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    strategy: 'A',
                    budget: 5000
                };
            }

            var self = this;
            var onLang = function() { try { self._updateBriefing(window.mySimulation.state); } catch (e) {} };
            try { if (window.mySimulation && window.mySimulation.eventBus && typeof window.mySimulation.eventBus.on === 'function') window.mySimulation.eventBus.on('language:changed', onLang); } catch (e) {}
            try { document.addEventListener('express:langchanged', onLang); } catch (e) {}

            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var strategyEl = document.getElementById('strategySelect');
            if (strategyEl) decisions.strategy = strategyEl.value;

            var budgetEl = document.getElementById('budgetInput');
            if (budgetEl) decisions.budget = parseFloat(budgetEl.value) || 0;

            if (decisions.budget < 0 || decisions.budget > 25000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            var currentState = window.mySimulation.state;
            if (decisions.budget > currentState.domainState.cash) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('insufficient_funds'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            if (!ds._snap) ds._snap = {};
            if (ds._snap[round]) { var _s = JSON.parse(ds._snap[round]); for (var _k in _s) { ds[_k] = _s[_k]; } }
            var _sk = ['cash','reputationTA','reputationGoogle','socialSentiment','bookingsNextMonth','totalRecoveryCost','reputationHistory','bookingHistory','sentimentHistory'];
            var _so = {}; for (var _i = 0; _i < _sk.length; _i++) { _so[_sk[_i]] = ds[_sk[_i]]; }
            ds._snap[round] = JSON.stringify(_so);
            var strat = d.strategy;
            var budget = d.budget;

            var repChange = 0;
            var sentChange = 0;
            var bookChange = 0;
            var budgetMult = Math.min(budget / 10000, 1.5);

            if (round === 1) {
                if (strat === 'A') {
                    repChange = 0.02 + (budgetMult * 0.03);
                    sentChange = 3 + Math.round(budgetMult * 5);
                    bookChange = -2;
                } else if (strat === 'B') {
                    repChange = -0.03;
                    sentChange = -5;
                    bookChange = -5;
                } else if (strat === 'C') {
                    repChange = -0.05;
                    sentChange = -8;
                    bookChange = -7;
                } else if (strat === 'D') {
                    repChange = -0.12;
                    sentChange = -18;
                    bookChange = -14;
                } else if (strat === 'E') {
                    repChange = 0.04 + (budgetMult * 0.04);
                    sentChange = 6 + Math.round(budgetMult * 6);
                    bookChange = -1;
                }
            } else if (round === 2) {
                if (strat === 'A') {
                    repChange = -0.08;
                    sentChange = -10;
                    bookChange = -8;
                } else if (strat === 'B') {
                    repChange = -0.15;
                    sentChange = -22;
                    bookChange = -15;
                } else if (strat === 'C') {
                    var compCost = 9000;
                    repChange = 0.05 + (budgetMult * 0.02);
                    sentChange = 12 + Math.round(budgetMult * 4);
                    bookChange = 3;
                    budget = Math.max(budget, compCost);
                } else if (strat === 'D') {
                    var recCost = 12600;
                    repChange = 0.08 + (budgetMult * 0.03);
                    sentChange = 18 + Math.round(budgetMult * 5);
                    bookChange = 5;
                    budget = Math.max(budget, recCost);
                } else if (strat === 'E') {
                    var luck = 0.7 + (Math.random() * 0.3);
                    repChange = 0.06 * luck + (budgetMult * 0.04);
                    sentChange = Math.round(15 * luck);
                    bookChange = Math.round(4 * luck);
                }
            } else if (round === 3) {
                if (strat === 'A') {
                    repChange = 0.02 + (budgetMult * 0.01);
                    sentChange = 3;
                    bookChange = 5 + Math.round(budgetMult * 3);
                } else if (strat === 'B') {
                    repChange = 0.01;
                    sentChange = 2;
                    bookChange = 8 + Math.round(budgetMult * 4);
                } else if (strat === 'C') {
                    repChange = 0.04 + (budgetMult * 0.02);
                    sentChange = 10 + Math.round(budgetMult * 5);
                    bookChange = 3;
                } else if (strat === 'D') {
                    repChange = 0.06 + (budgetMult * 0.02);
                    sentChange = 8 + Math.round(budgetMult * 4);
                    bookChange = 10 + Math.round(budgetMult * 5);
                } else if (strat === 'E') {
                    repChange = 0.03 + (budgetMult * 0.02);
                    sentChange = 15 + Math.round(budgetMult * 5);
                    bookChange = 6 + Math.round(budgetMult * 3);
                }
            } else if (round === 4) {
                if (strat === 'A') {
                    repChange = 0.05 + (budgetMult * 0.02);
                    sentChange = 5;
                    bookChange = 4;
                } else if (strat === 'B') {
                    repChange = 0.02;
                    sentChange = 3;
                    bookChange = 2;
                } else if (strat === 'C') {
                    repChange = 0.03;
                    sentChange = 4;
                    bookChange = 3;
                } else if (strat === 'D') {
                    repChange = 0.06 + (budgetMult * 0.02);
                    sentChange = 6 + Math.round(budgetMult * 3);
                    bookChange = 6 + Math.round(budgetMult * 2);
                } else if (strat === 'E') {
                    repChange = 0.10 + (budgetMult * 0.03);
                    sentChange = 10 + Math.round(budgetMult * 5);
                    bookChange = 10 + Math.round(budgetMult * 4);
                }
            }

            ds.reputationTA = Math.round(Math.max(1, Math.min(5, ds.reputationTA + repChange)) * 100) / 100;
            ds.reputationGoogle = Math.round(Math.max(1, Math.min(5, ds.reputationGoogle + (repChange * 0.8))) * 100) / 100;
            ds.socialSentiment = Math.max(0, Math.min(100, ds.socialSentiment + sentChange));
            ds.bookingsNextMonth = Math.max(0, Math.round(ds.bookingsNextMonth + bookChange));
            ds.cash = Math.round(ds.cash - budget);
            ds.totalRecoveryCost = Math.round(ds.totalRecoveryCost + budget);

            var baseMonthlyRevenue = 242000;
            var repMultiplier = ds.reputationTA / 4.7;
            var projectedRevenue = Math.round(baseMonthlyRevenue * repMultiplier);
            var revenueDelta = projectedRevenue - baseMonthlyRevenue;

            ds.reputationHistory.push(ds.reputationTA);
            ds.bookingHistory.push(ds.bookingsNextMonth);
            ds.sentimentHistory.push(ds.socialSentiment);

            var _score = this._computeScore(ds.reputationTA, ds.socialSentiment, ds.bookingsNextMonth, ds.totalRecoveryCost);
            ds.performance = { overallScore: _score, grade: this._gradeFor(_score), tier: this._tierFor(_score) };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                strategy: strat,
                budget: budget,
                reputationTA: ds.reputationTA,
                reputationGoogle: ds.reputationGoogle,
                socialSentiment: ds.socialSentiment,
                bookingsNextMonth: ds.bookingsNextMonth,
                projectedRevenue: projectedRevenue,
                revenueDelta: revenueDelta,
                cash: ds.cash,
                overallScore: ds.performance.overallScore,
                grade: ds.performance.grade,
                performanceTier: ds.performance.tier
            };
        }

