        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var isEs = (this._lang() === 'es');

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.innerHTML = isEs ? round.titleEs : round.titleEn;

            var textEl = document.getElementById('briefingText');
            if (textEl) textEl.innerHTML = isEs ? round.descEs : round.descEn;

            var selectEl = document.getElementById('strategySelect');
            if (selectEl) {
                var strats = isEs ? round.stratEs : round.stratEn;
                var values = ['A', 'B', 'C', 'D', 'E'];
                selectEl.innerHTML = '';
                for (var i = 0; i < strats.length; i++) {
                    var opt = document.createElement('option');
                    opt.value = values[i];
                    opt.textContent = strats[i];
                    selectEl.appendChild(opt);
                }
            }
        }
